SELECT a.id,a.ts,a.dur,a.surface_frame_token,a.display_frame_token,a.layer_name,a.present_type,a.jank_type,a.on_time_finish, f.ts AS display_start_ns,f.dur AS display_duration_ns,f.ts+f.dur AS display_end_ns,f.present_type AS display_present_type FROM actual_frame_timeline_slice a JOIN process p ON p.upid=a.upid LEFT JOIN actual_frame_timeline_slice f ON f.display_frame_token=a.display_frame_token AND f.surface_frame_token IS NULL AND f.dur>0 WHERE p.pid=23055 AND a.layer_name LIKE '%MainActivity%' AND a.dur>0 ORDER BY a.ts
